gameActivityImportAdditions.insert:
import androidx.core.util.Consumer;
import androidx.window.java.layout.WindowInfoTrackerCallbackAdapter;
import androidx.window.layout.DisplayFeature;
import androidx.window.layout.FoldingFeature;
import androidx.window.layout.WindowInfoTracker;
import androidx.window.layout.WindowLayoutInfo;

gameActivityClassAdditions.insert:
private boolean OpenMobileDeviceHasSavedOrientationPolicy = false;
private int OpenMobileDeviceSavedOrientationPolicy =
	android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED;
private boolean OpenMobileDeviceWindowMonitoring = false;
private WindowInfoTrackerCallbackAdapter OpenMobileDeviceWindowInfoTracker;
private Consumer<WindowLayoutInfo> OpenMobileDeviceWindowLayoutConsumer;
private android.hardware.display.DisplayManager.DisplayListener
	OpenMobileDeviceDisplayListener;
private volatile float[] OpenMobileDeviceFoldableInfo = new float[0];

public native void nativeOpenMobileDeviceWindowChanged();

private void OpenMobileDeviceNotifyWindowChanged()
{
	if (OpenMobileDeviceWindowMonitoring)
	{
		nativeOpenMobileDeviceWindowChanged();
	}
}

private void OpenMobileDeviceUpdateFoldableInfo(
	WindowLayoutInfo windowLayoutInfo
)
{
	if (!OpenMobileDeviceWindowMonitoring)
	{
		return;
	}
	android.view.Window window = getWindow();
	android.view.View decorView = window == null ? null : window.getDecorView();
	float density = getResources().getDisplayMetrics().density;
	if (decorView == null || density <= 0.0f)
	{
		OpenMobileDeviceFoldableInfo = new float[0];
		OpenMobileDeviceNotifyWindowChanged();
		return;
	}
	for (DisplayFeature displayFeature : windowLayoutInfo.getDisplayFeatures())
	{
		if (!(displayFeature instanceof FoldingFeature))
		{
			continue;
		}
		FoldingFeature foldingFeature = (FoldingFeature)displayFeature;
		int state = 0;
		if (foldingFeature.getState() == FoldingFeature.State.FLAT)
		{
			state = 1;
		}
		else if (foldingFeature.getState()
			== FoldingFeature.State.HALF_OPENED)
		{
			state = 2;
		}
		int orientation = 0;
		if (foldingFeature.getOrientation()
			== FoldingFeature.Orientation.HORIZONTAL)
		{
			orientation = 1;
		}
		else if (foldingFeature.getOrientation()
			== FoldingFeature.Orientation.VERTICAL)
		{
			orientation = 2;
		}
		android.graphics.Rect bounds = foldingFeature.getBounds();
		int[] decorLocation = new int[2];
		decorView.getLocationInWindow(decorLocation);
		OpenMobileDeviceFoldableInfo = new float[] {
			1.0f,
			(float)state,
			(float)orientation,
			foldingFeature.isSeparating() ? 1.0f : 0.0f,
			(float)(bounds.left - decorLocation[0]),
			(float)(bounds.top - decorLocation[1]),
			(float)(bounds.right - decorLocation[0]),
			(float)(bounds.bottom - decorLocation[1]),
			density
		};
		OpenMobileDeviceNotifyWindowChanged();
		return;
	}
	OpenMobileDeviceFoldableInfo = new float[] {1.0f};
	OpenMobileDeviceNotifyWindowChanged();
}

public boolean AndroidThunkJava_OpenMobileDeviceStartWindowMonitoring()
{
	if (OpenMobileDeviceWindowMonitoring)
	{
		return true;
	}
	OpenMobileDeviceWindowMonitoring = true;
	try
	{
		OpenMobileDeviceWindowInfoTracker =
			new WindowInfoTrackerCallbackAdapter(
				WindowInfoTracker.getOrCreate(this)
			);
		OpenMobileDeviceWindowLayoutConsumer =
			new Consumer<WindowLayoutInfo>()
			{
				@Override
				public void accept(WindowLayoutInfo windowLayoutInfo)
				{
					OpenMobileDeviceUpdateFoldableInfo(windowLayoutInfo);
				}
			};
		java.util.concurrent.Executor executor =
			new java.util.concurrent.Executor()
			{
				@Override
				public void execute(Runnable command)
				{
					runOnUiThread(command);
				}
			};
		OpenMobileDeviceWindowInfoTracker.addWindowLayoutInfoListener(
			this,
			executor,
			OpenMobileDeviceWindowLayoutConsumer
		);
		android.hardware.display.DisplayManager displayManager =
			(android.hardware.display.DisplayManager)getSystemService(
				android.content.Context.DISPLAY_SERVICE
			);
		if (displayManager != null)
		{
			OpenMobileDeviceDisplayListener =
				new android.hardware.display.DisplayManager.DisplayListener()
				{
					@Override
					public void onDisplayAdded(int displayId)
					{
						OpenMobileDeviceNotifyWindowChanged();
					}

					@Override
					public void onDisplayChanged(int displayId)
					{
						OpenMobileDeviceNotifyWindowChanged();
					}

					@Override
					public void onDisplayRemoved(int displayId)
					{
						OpenMobileDeviceNotifyWindowChanged();
					}
				};
			displayManager.registerDisplayListener(
				OpenMobileDeviceDisplayListener,
				new android.os.Handler(android.os.Looper.getMainLooper())
			);
		}
		return true;
	}
	catch (RuntimeException ignored)
	{
		AndroidThunkJava_OpenMobileDeviceStopWindowMonitoring();
		return false;
	}
}

public void AndroidThunkJava_OpenMobileDeviceStopWindowMonitoring()
{
	OpenMobileDeviceWindowMonitoring = false;
	if (OpenMobileDeviceDisplayListener != null)
	{
		android.hardware.display.DisplayManager displayManager =
			(android.hardware.display.DisplayManager)getSystemService(
				android.content.Context.DISPLAY_SERVICE
			);
		if (displayManager != null)
		{
			try
			{
				displayManager.unregisterDisplayListener(
					OpenMobileDeviceDisplayListener
				);
			}
			catch (RuntimeException ignored)
			{
			}
		}
	}
	OpenMobileDeviceDisplayListener = null;
	if (OpenMobileDeviceWindowInfoTracker != null
		&& OpenMobileDeviceWindowLayoutConsumer != null)
	{
		try
		{
			OpenMobileDeviceWindowInfoTracker
				.removeWindowLayoutInfoListener(
					OpenMobileDeviceWindowLayoutConsumer
				);
		}
		catch (RuntimeException ignored)
		{
		}
	}
	OpenMobileDeviceWindowInfoTracker = null;
	OpenMobileDeviceWindowLayoutConsumer = null;
	OpenMobileDeviceFoldableInfo = new float[0];
}

public float[] AndroidThunkJava_OpenMobileDeviceGetFoldableInfo()
{
	return OpenMobileDeviceFoldableInfo.clone();
}

@Override
public void onMultiWindowModeChanged(boolean isInMultiWindowMode)
{
	super.onMultiWindowModeChanged(isInMultiWindowMode);
	OpenMobileDeviceNotifyWindowChanged();
}

@Override
public void onPictureInPictureModeChanged(boolean isInPictureInPictureMode)
{
	super.onPictureInPictureModeChanged(isInPictureInPictureMode);
	OpenMobileDeviceNotifyWindowChanged();
}

public boolean AndroidThunkJava_OpenMobileDeviceApplyOrientationPolicy(
	final int policy
)
{
	final int requestedOrientation;
	switch (policy)
	{
		case 0:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED;
			break;
		case 1:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT;
			break;
		case 2:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE;
			break;
		case 3:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT;
			break;
		case 4:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_REVERSE_PORTRAIT;
			break;
		case 5:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE;
			break;
		case 6:
			requestedOrientation =
				android.content.pm.ActivityInfo.SCREEN_ORIENTATION_REVERSE_LANDSCAPE;
			break;
		default:
			return false;
	}

	runOnUiThread(new Runnable()
	{
		@Override
		public void run()
		{
			if (!OpenMobileDeviceHasSavedOrientationPolicy)
			{
				OpenMobileDeviceSavedOrientationPolicy =
					getRequestedOrientation();
				OpenMobileDeviceHasSavedOrientationPolicy = true;
			}
			int effectiveOrientation = policy == 0
				? OpenMobileDeviceSavedOrientationPolicy
				: requestedOrientation;
			setRequestedOrientation(effectiveOrientation);
		}
	});
	return true;
}

public void AndroidThunkJava_OpenMobileDeviceClearOrientationPolicy()
{
	runOnUiThread(new Runnable()
	{
		@Override
		public void run()
		{
			if (!OpenMobileDeviceHasSavedOrientationPolicy)
			{
				return;
			}
			setRequestedOrientation(OpenMobileDeviceSavedOrientationPolicy);
			OpenMobileDeviceHasSavedOrientationPolicy = false;
		}
	});
}

private boolean OpenMobileDeviceHasSavedPreferredRefreshRate = false;
private float OpenMobileDeviceSavedPreferredRefreshRate = 0.0f;

public boolean AndroidThunkJava_OpenMobileDeviceApplyPreferredRefreshRate(
	final float preferredRefreshRate
)
{
	if (Float.isNaN(preferredRefreshRate)
		|| Float.isInfinite(preferredRefreshRate)
		|| preferredRefreshRate <= 0.0f)
	{
		return false;
	}
	final android.view.Window window = getWindow();
	if (window == null)
	{
		return false;
	}
	runOnUiThread(new Runnable()
	{
		@Override
		public void run()
		{
			android.view.WindowManager.LayoutParams attributes =
				window.getAttributes();
			if (!OpenMobileDeviceHasSavedPreferredRefreshRate)
			{
				OpenMobileDeviceSavedPreferredRefreshRate =
					attributes.preferredRefreshRate;
				OpenMobileDeviceHasSavedPreferredRefreshRate = true;
			}
			attributes.preferredRefreshRate = preferredRefreshRate;
			window.setAttributes(attributes);
		}
	});
	return true;
}

public void AndroidThunkJava_OpenMobileDeviceClearPreferredRefreshRate()
{
	final android.view.Window window = getWindow();
	if (window == null)
	{
		return;
	}
	runOnUiThread(new Runnable()
	{
		@Override
		public void run()
		{
			if (!OpenMobileDeviceHasSavedPreferredRefreshRate)
			{
				return;
			}
			android.view.WindowManager.LayoutParams attributes =
				window.getAttributes();
			attributes.preferredRefreshRate =
				OpenMobileDeviceSavedPreferredRefreshRate;
			window.setAttributes(attributes);
			OpenMobileDeviceHasSavedPreferredRefreshRate = false;
		}
	});
}

private android.view.Window OpenMobileDeviceBrightnessWindow = null;
private boolean OpenMobileDeviceHasSavedBrightness = false;
private float OpenMobileDeviceSavedBrightness =
	android.view.WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE;
private float OpenMobileDeviceLastAppliedBrightness =
	android.view.WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE;

private boolean OpenMobileDeviceRunWindowTask(final Runnable task)
{
	if (android.os.Looper.myLooper()
		== android.os.Looper.getMainLooper())
	{
		try
		{
			task.run();
			return true;
		}
		catch (RuntimeException ignored)
		{
			return false;
		}
	}
	final java.util.concurrent.CountDownLatch latch =
		new java.util.concurrent.CountDownLatch(1);
	final java.util.concurrent.atomic.AtomicBoolean succeeded =
		new java.util.concurrent.atomic.AtomicBoolean(false);
	runOnUiThread(new Runnable()
	{
		@Override
		public void run()
		{
			try
			{
				task.run();
				succeeded.set(true);
			}
			catch (RuntimeException ignored)
			{
			}
			finally
			{
				latch.countDown();
			}
		}
	});
	try
	{
		return latch.await(2, java.util.concurrent.TimeUnit.SECONDS)
			&& succeeded.get();
	}
	catch (InterruptedException ignored)
	{
		Thread.currentThread().interrupt();
		return false;
	}
}

private float OpenMobileDeviceReadBrightness(
	android.view.Window window
)
{
	if (window == null)
	{
		return Float.NaN;
	}
	float windowBrightness = window.getAttributes().screenBrightness;
	if (windowBrightness >= 0.0f)
	{
		return Math.max(0.0f, Math.min(1.0f, windowBrightness));
	}
	if (android.os.Build.VERSION.SDK_INT >= 31)
	{
		android.view.View decorView = window.getDecorView();
		android.view.Display display = decorView == null
			? null
			: decorView.getDisplay();
		android.hardware.display.BrightnessInfo brightnessInfo =
			display == null ? null : display.getBrightnessInfo();
		if (brightnessInfo != null
			&& !Float.isNaN(brightnessInfo.brightness)
			&& !Float.isInfinite(brightnessInfo.brightness))
		{
			return Math.max(
				0.0f,
				Math.min(1.0f, brightnessInfo.brightness)
			);
		}
	}
	int systemBrightness = android.provider.Settings.System.getInt(
		getContentResolver(),
		android.provider.Settings.System.SCREEN_BRIGHTNESS,
		-1
	);
	return systemBrightness < 0
		? Float.NaN
		: Math.max(0.0f, Math.min(1.0f, systemBrightness / 255.0f));
}

private void OpenMobileDeviceClearBrightnessOnUiThread()
{
	if (!OpenMobileDeviceHasSavedBrightness
		|| OpenMobileDeviceBrightnessWindow == null)
	{
		OpenMobileDeviceBrightnessWindow = null;
		OpenMobileDeviceHasSavedBrightness = false;
		return;
	}
	android.view.WindowManager.LayoutParams attributes =
		OpenMobileDeviceBrightnessWindow.getAttributes();
	if (Math.abs(
		attributes.screenBrightness
			- OpenMobileDeviceLastAppliedBrightness
	) <= 0.001f)
	{
		attributes.screenBrightness = OpenMobileDeviceSavedBrightness;
		OpenMobileDeviceBrightnessWindow.setAttributes(attributes);
	}
	OpenMobileDeviceBrightnessWindow = null;
	OpenMobileDeviceHasSavedBrightness = false;
	OpenMobileDeviceSavedBrightness =
		android.view.WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE;
	OpenMobileDeviceLastAppliedBrightness =
		android.view.WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE;
}

public float[] AndroidThunkJava_OpenMobileDeviceGetBrightness()
{
	final float[] result = new float[] { Float.NaN };
	boolean completed = OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			result[0] = OpenMobileDeviceReadBrightness(getWindow());
		}
	});
	return completed && !Float.isNaN(result[0])
		? new float[] { result[0] }
		: new float[0];
}

public float[] AndroidThunkJava_OpenMobileDeviceApplyBrightness(
	final float brightness
)
{
	if (Float.isNaN(brightness) || Float.isInfinite(brightness)
		|| brightness < 0.0f || brightness > 1.0f)
	{
		return new float[0];
	}
	final float[] result = new float[] { Float.NaN };
	boolean completed = OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			android.view.Window window = getWindow();
			if (window == null)
			{
				return;
			}
			if (OpenMobileDeviceBrightnessWindow != window)
			{
				OpenMobileDeviceClearBrightnessOnUiThread();
			}
			android.view.WindowManager.LayoutParams attributes =
				window.getAttributes();
			if (!OpenMobileDeviceHasSavedBrightness)
			{
				OpenMobileDeviceBrightnessWindow = window;
				OpenMobileDeviceSavedBrightness =
					attributes.screenBrightness;
				OpenMobileDeviceHasSavedBrightness = true;
			}
			else if (Math.abs(
				attributes.screenBrightness
					- OpenMobileDeviceLastAppliedBrightness
			) > 0.001f)
			{
				OpenMobileDeviceSavedBrightness =
					attributes.screenBrightness;
			}
			attributes.screenBrightness = brightness;
			window.setAttributes(attributes);
			float effective = window.getAttributes().screenBrightness;
			if (effective >= 0.0f && effective <= 1.0f)
			{
				OpenMobileDeviceLastAppliedBrightness = effective;
				result[0] = effective;
			}
		}
	});
	if (!completed)
	{
		runOnUiThread(new Runnable()
		{
			@Override
			public void run()
			{
				OpenMobileDeviceClearBrightnessOnUiThread();
			}
		});
	}
	return completed && !Float.isNaN(result[0])
		? new float[] { result[0] }
		: new float[0];
}

public void AndroidThunkJava_OpenMobileDeviceClearBrightness()
{
	OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			OpenMobileDeviceClearBrightnessOnUiThread();
		}
	});
}

private android.view.Window OpenMobileDeviceKeepScreenAwakeWindow = null;
private boolean OpenMobileDeviceHasSavedKeepScreenAwake = false;
private boolean OpenMobileDeviceSavedKeepScreenAwake = false;

private void OpenMobileDeviceClearKeepScreenAwakeOnUiThread()
{
	if (!OpenMobileDeviceHasSavedKeepScreenAwake
		|| OpenMobileDeviceKeepScreenAwakeWindow == null)
	{
		OpenMobileDeviceKeepScreenAwakeWindow = null;
		OpenMobileDeviceHasSavedKeepScreenAwake = false;
		return;
	}
	int flag = android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON;
	boolean effective =
		(OpenMobileDeviceKeepScreenAwakeWindow.getAttributes().flags & flag)
			!= 0;
	if (!OpenMobileDeviceSavedKeepScreenAwake && effective)
	{
		OpenMobileDeviceKeepScreenAwakeWindow.clearFlags(flag);
	}
	OpenMobileDeviceKeepScreenAwakeWindow = null;
	OpenMobileDeviceHasSavedKeepScreenAwake = false;
	OpenMobileDeviceSavedKeepScreenAwake = false;
}

public boolean AndroidThunkJava_OpenMobileDeviceApplyKeepScreenAwake()
{
	final java.util.concurrent.atomic.AtomicBoolean result =
		new java.util.concurrent.atomic.AtomicBoolean(false);
	boolean completed = OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			android.view.Window window = getWindow();
			if (window == null)
			{
				return;
			}
			if (OpenMobileDeviceKeepScreenAwakeWindow != window)
			{
				OpenMobileDeviceClearKeepScreenAwakeOnUiThread();
			}
			int flag =
				android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON;
			if (!OpenMobileDeviceHasSavedKeepScreenAwake)
			{
				OpenMobileDeviceKeepScreenAwakeWindow = window;
				OpenMobileDeviceSavedKeepScreenAwake =
					(window.getAttributes().flags & flag) != 0;
				OpenMobileDeviceHasSavedKeepScreenAwake = true;
			}
			window.addFlags(flag);
			result.set((window.getAttributes().flags & flag) != 0);
		}
	});
	if (!completed)
	{
		runOnUiThread(new Runnable()
		{
			@Override
			public void run()
			{
				OpenMobileDeviceClearKeepScreenAwakeOnUiThread();
			}
		});
	}
	return completed && result.get();
}

public void AndroidThunkJava_OpenMobileDeviceClearKeepScreenAwake()
{
	OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			OpenMobileDeviceClearKeepScreenAwakeOnUiThread();
		}
	});
}

private android.view.Window OpenMobileDeviceSystemUiWindow = null;
private boolean OpenMobileDeviceHasSavedSystemUi = false;
private int OpenMobileDeviceSavedSystemUiVisibility = 0;
private int OpenMobileDeviceSavedFitInsetsTypes = 0;
private boolean OpenMobileDeviceSavedDecorFitsSystemWindows = true;
private boolean OpenMobileDeviceSavedStatusBarsVisible = true;
private boolean OpenMobileDeviceSavedNavigationBarsVisible = true;
private boolean OpenMobileDeviceSavedInsetsVisibilityAvailable = false;
private int OpenMobileDeviceSavedSystemBarsBehavior = 0;

private void OpenMobileDeviceNotifySystemUiSettled(
	final android.view.View decorView
)
{
	if (decorView == null)
	{
		return;
	}
	decorView.postOnAnimation(new Runnable()
	{
		@Override
		public void run()
		{
			decorView.postOnAnimation(new Runnable()
			{
				@Override
				public void run()
				{
					decorView.requestApplyInsets();
					OpenMobileDeviceNotifyWindowChanged();
				}
			});
		}
	});
}

private void OpenMobileDeviceClearSystemUiModeOnUiThread()
{
	if (!OpenMobileDeviceHasSavedSystemUi
		|| OpenMobileDeviceSystemUiWindow == null)
	{
		OpenMobileDeviceSystemUiWindow = null;
		OpenMobileDeviceHasSavedSystemUi = false;
		return;
	}
	android.view.Window window = OpenMobileDeviceSystemUiWindow;
	android.view.View decorView = window.getDecorView();
	if (android.os.Build.VERSION.SDK_INT >= 30)
	{
		window.setDecorFitsSystemWindows(
			OpenMobileDeviceSavedDecorFitsSystemWindows
		);
		android.view.WindowManager.LayoutParams attributes =
			window.getAttributes();
		attributes.setFitInsetsTypes(
			OpenMobileDeviceSavedFitInsetsTypes
		);
		window.setAttributes(attributes);
		android.view.WindowInsetsController controller =
			decorView.getWindowInsetsController();
		if (controller != null)
		{
			controller.setSystemBarsBehavior(
				OpenMobileDeviceSavedSystemBarsBehavior
			);
			if (OpenMobileDeviceSavedInsetsVisibilityAvailable)
			{
				int statusBars =
					android.view.WindowInsets.Type.statusBars();
				int navigationBars =
					android.view.WindowInsets.Type.navigationBars();
				if (OpenMobileDeviceSavedStatusBarsVisible)
				{
					controller.show(statusBars);
				}
				else
				{
					controller.hide(statusBars);
				}
				if (OpenMobileDeviceSavedNavigationBarsVisible)
				{
					controller.show(navigationBars);
				}
				else
				{
					controller.hide(navigationBars);
				}
			}
		}
	}
	decorView.setSystemUiVisibility(
		OpenMobileDeviceSavedSystemUiVisibility
	);
	OpenMobileDeviceNotifySystemUiSettled(decorView);
	OpenMobileDeviceSystemUiWindow = null;
	OpenMobileDeviceHasSavedSystemUi = false;
	OpenMobileDeviceSavedInsetsVisibilityAvailable = false;
}

public int[] AndroidThunkJava_OpenMobileDeviceApplySystemUiMode(
	final int mode
)
{
	if (mode < 0 || mode > 2)
	{
		return new int[0];
	}
	final java.util.concurrent.atomic.AtomicInteger effectiveMode =
		new java.util.concurrent.atomic.AtomicInteger(-1);
	boolean completed = OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			android.view.Window window = getWindow();
			android.view.View decorView = window == null
				? null
				: window.getDecorView();
			if (window == null || decorView == null)
			{
				return;
			}
			if (android.os.Build.VERSION.SDK_INT >= 30
				&& (decorView.getWindowInsetsController() == null
					|| decorView.getRootWindowInsets() == null))
			{
				return;
			}
			if (OpenMobileDeviceSystemUiWindow != window)
			{
				OpenMobileDeviceClearSystemUiModeOnUiThread();
			}
			if (!OpenMobileDeviceHasSavedSystemUi)
			{
				OpenMobileDeviceSystemUiWindow = window;
				OpenMobileDeviceSavedSystemUiVisibility =
					decorView.getSystemUiVisibility();
				if (android.os.Build.VERSION.SDK_INT >= 30)
				{
					android.view.WindowManager.LayoutParams attributes =
						window.getAttributes();
					OpenMobileDeviceSavedFitInsetsTypes =
						attributes.getFitInsetsTypes();
					int systemBars =
						android.view.WindowInsets.Type.systemBars();
					OpenMobileDeviceSavedDecorFitsSystemWindows =
						(OpenMobileDeviceSavedFitInsetsTypes & systemBars)
							== systemBars;
					android.view.WindowInsets insets =
						decorView.getRootWindowInsets();
					if (insets != null)
					{
						OpenMobileDeviceSavedStatusBarsVisible =
							insets.isVisible(
								android.view.WindowInsets.Type.statusBars()
							);
						OpenMobileDeviceSavedNavigationBarsVisible =
							insets.isVisible(
								android.view.WindowInsets.Type.navigationBars()
							);
						OpenMobileDeviceSavedInsetsVisibilityAvailable =
							true;
					}
					android.view.WindowInsetsController controller =
						decorView.getWindowInsetsController();
					if (controller != null)
					{
						OpenMobileDeviceSavedSystemBarsBehavior =
							controller.getSystemBarsBehavior();
					}
				}
				OpenMobileDeviceHasSavedSystemUi = true;
			}

			if (android.os.Build.VERSION.SDK_INT >= 30)
			{
				boolean decorFits = mode == 0;
				window.setDecorFitsSystemWindows(decorFits);
				android.view.WindowInsetsController controller =
					decorView.getWindowInsetsController();
				if (controller == null)
				{
					return;
				}
				int systemBars =
					android.view.WindowInsets.Type.systemBars();
				if (mode == 2)
				{
					controller.setSystemBarsBehavior(
						android.view.WindowInsetsController
							.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE
					);
					controller.hide(systemBars);
				}
				else
				{
					controller.setSystemBarsBehavior(
						android.view.WindowInsetsController.BEHAVIOR_DEFAULT
					);
					controller.show(systemBars);
				}
				int appliedMode = mode;
				if (mode == 0)
				{
					int fitTypes =
						window.getAttributes().getFitInsetsTypes();
					if ((fitTypes & systemBars) != systemBars)
					{
						appliedMode = 1;
					}
				}
				effectiveMode.set(appliedMode);
			}
			else
			{
				int controlledFlags =
					android.view.View.SYSTEM_UI_FLAG_LOW_PROFILE
					| android.view.View.SYSTEM_UI_FLAG_FULLSCREEN
					| android.view.View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
					| android.view.View.SYSTEM_UI_FLAG_IMMERSIVE
					| android.view.View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
					| android.view.View.SYSTEM_UI_FLAG_LAYOUT_STABLE
					| android.view.View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
					| android.view.View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION;
				int visibility =
					OpenMobileDeviceSavedSystemUiVisibility
						& ~controlledFlags;
				if (mode >= 1)
				{
					visibility |=
						android.view.View.SYSTEM_UI_FLAG_LAYOUT_STABLE
						| android.view.View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
						| android.view.View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION;
				}
				if (mode == 2)
				{
					visibility |=
						android.view.View.SYSTEM_UI_FLAG_FULLSCREEN
						| android.view.View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
						| android.view.View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY;
				}
				decorView.setSystemUiVisibility(visibility);
				effectiveMode.set(mode);
			}
			OpenMobileDeviceNotifySystemUiSettled(decorView);
		}
	});
	if (!completed)
	{
		runOnUiThread(new Runnable()
		{
			@Override
			public void run()
			{
				OpenMobileDeviceClearSystemUiModeOnUiThread();
			}
		});
	}
	return completed && effectiveMode.get() >= 0
		? new int[] { effectiveMode.get() }
		: new int[0];
}

public void AndroidThunkJava_OpenMobileDeviceClearSystemUiMode()
{
	OpenMobileDeviceRunWindowTask(new Runnable()
	{
		@Override
		public void run()
		{
			OpenMobileDeviceClearSystemUiModeOnUiThread();
		}
	});
}

public float[] AndroidThunkJava_OpenMobileDeviceGetWindowInsets()
{
	android.view.Window window = getWindow();
	android.view.View decorView = window == null ? null : window.getDecorView();
	android.view.WindowInsets windowInsets = decorView == null
		? null
		: decorView.getRootWindowInsets();
	float density = getResources().getDisplayMetrics().density;
	if (windowInsets == null || density <= 0.0f)
	{
		return new float[0];
	}

	int barLeft;
	int barTop;
	int barRight;
	int barBottom;
	int cutoutLeft = 0;
	int cutoutTop = 0;
	int cutoutRight = 0;
	int cutoutBottom = 0;
	int gestureLeft = 0;
	int gestureTop = 0;
	int gestureRight = 0;
	int gestureBottom = 0;
	boolean gesturesAvailable = false;
	if (android.os.Build.VERSION.SDK_INT >= 30)
	{
		android.graphics.Insets bars = windowInsets.getInsets(
			android.view.WindowInsets.Type.systemBars()
		);
		android.graphics.Insets cutout = windowInsets.getInsets(
			android.view.WindowInsets.Type.displayCutout()
		);
		android.graphics.Insets gestures = windowInsets.getInsets(
			android.view.WindowInsets.Type.systemGestures()
		);
		barLeft = bars.left;
		barTop = bars.top;
		barRight = bars.right;
		barBottom = bars.bottom;
		cutoutLeft = cutout.left;
		cutoutTop = cutout.top;
		cutoutRight = cutout.right;
		cutoutBottom = cutout.bottom;
		gestureLeft = gestures.left;
		gestureTop = gestures.top;
		gestureRight = gestures.right;
		gestureBottom = gestures.bottom;
		gesturesAvailable = true;
	}
	else
	{
		barLeft = Math.min(
			windowInsets.getSystemWindowInsetLeft(),
			windowInsets.getStableInsetLeft()
		);
		barTop = Math.min(
			windowInsets.getSystemWindowInsetTop(),
			windowInsets.getStableInsetTop()
		);
		barRight = Math.min(
			windowInsets.getSystemWindowInsetRight(),
			windowInsets.getStableInsetRight()
		);
		barBottom = Math.min(
			windowInsets.getSystemWindowInsetBottom(),
			windowInsets.getStableInsetBottom()
		);
		if (android.os.Build.VERSION.SDK_INT >= 28)
		{
			android.view.DisplayCutout cutout = windowInsets.getDisplayCutout();
			if (cutout != null)
			{
				cutoutLeft = cutout.getSafeInsetLeft();
				cutoutTop = cutout.getSafeInsetTop();
				cutoutRight = cutout.getSafeInsetRight();
				cutoutBottom = cutout.getSafeInsetBottom();
			}
		}
		if (android.os.Build.VERSION.SDK_INT >= 29)
		{
			android.graphics.Insets gestures =
				windowInsets.getSystemGestureInsets();
			gestureLeft = gestures.left;
			gestureTop = gestures.top;
			gestureRight = gestures.right;
			gestureBottom = gestures.bottom;
			gesturesAvailable = true;
		}
	}

	return new float[] {
		density,
		1.0f,
		Math.max(barLeft, cutoutLeft),
		Math.max(barTop, cutoutTop),
		Math.max(barRight, cutoutRight),
		Math.max(barBottom, cutoutBottom),
		1.0f,
		barLeft,
		barTop,
		barRight,
		barBottom,
		gesturesAvailable ? 1.0f : 0.0f,
		gestureLeft,
		gestureTop,
		gestureRight,
		gestureBottom
	};
}

public float[] AndroidThunkJava_OpenMobileDeviceGetDisplayCutouts()
{
	if (android.os.Build.VERSION.SDK_INT < 28)
	{
		return new float[0];
	}
	android.view.Window window = getWindow();
	android.view.View decorView = window == null ? null : window.getDecorView();
	android.view.WindowInsets windowInsets = decorView == null
		? null
		: decorView.getRootWindowInsets();
	float density = getResources().getDisplayMetrics().density;
	if (windowInsets == null || density <= 0.0f)
	{
		return new float[0];
	}
	int[] windowLocation = new int[2];
	decorView.getLocationOnScreen(windowLocation);
	android.view.DisplayCutout displayCutout = windowInsets.getDisplayCutout();
	java.util.List<android.graphics.Rect> boundingRects = displayCutout == null
		? java.util.Collections.<android.graphics.Rect>emptyList()
		: displayCutout.getBoundingRects();
	float[] result = new float[10 + boundingRects.size() * 4];
	result[0] = density;
	result[1] = windowLocation[0];
	result[2] = windowLocation[1];
	result[3] = 1.0f;
	result[4] = android.os.Build.VERSION.SDK_INT >= 30 ? 1.0f : 0.0f;
	if (displayCutout != null && android.os.Build.VERSION.SDK_INT >= 30)
	{
		android.graphics.Insets waterfall = displayCutout.getWaterfallInsets();
		result[5] = waterfall.left;
		result[6] = waterfall.top;
		result[7] = waterfall.right;
		result[8] = waterfall.bottom;
	}
	result[9] = boundingRects.size();
	for (int index = 0; index < boundingRects.size(); ++index)
	{
		android.graphics.Rect rect = boundingRects.get(index);
		int firstValue = 10 + index * 4;
		result[firstValue] = rect.left;
		result[firstValue + 1] = rect.top;
		result[firstValue + 2] = rect.right;
		result[firstValue + 3] = rect.bottom;
	}
	return result;
}

public int[] AndroidThunkJava_OpenMobileDeviceGetWindowOrientation()
{
	android.view.Window window = getWindow();
	android.view.View decorView = window == null ? null : window.getDecorView();
	android.view.Display display = decorView == null
		? null
		: decorView.getDisplay();
	if (display == null)
	{
		return new int[0];
	}
	int rotation = display.getRotation();
	android.graphics.Point realSize = new android.graphics.Point();
	display.getRealSize(realSize);
	if (realSize.x <= 0 || realSize.y <= 0 || realSize.x == realSize.y)
	{
		return new int[0];
	}
	boolean naturalLandscape = rotation == android.view.Surface.ROTATION_0
		|| rotation == android.view.Surface.ROTATION_180
		? realSize.x > realSize.y
		: realSize.y > realSize.x;
	return new int[] { rotation, naturalLandscape ? 1 : 0 };
}

