public float AndroidThunkJava_OpenMobileDeviceGetThermalHeadroom(int forecastSeconds)
{
	if (android.os.Build.VERSION.SDK_INT < 30)
	{
		return Float.NaN;
	}
	android.os.PowerManager powerManager = (android.os.PowerManager)
		getSystemService(android.content.Context.POWER_SERVICE);
	if (powerManager == null)
	{
		return Float.NaN;
	}
	try
	{
		return powerManager.getThermalHeadroom(forecastSeconds);
	}
	catch (RuntimeException ignored)
	{
		return Float.NaN;
	}
}

public boolean AndroidThunkJava_OpenMobileDeviceStartBatteryMonitoring()
{
	if (OpenMobileDeviceBatteryReceiver != null)
	{
		return true;
	}
	OpenMobileDeviceBatteryReceiver = new android.content.BroadcastReceiver()
	{
		@Override
		public void onReceive(
			android.content.Context context,
			android.content.Intent intent
		)
		{
			nativeOpenMobileDeviceBatteryChanged();
		}
	};
	android.content.IntentFilter filter = new android.content.IntentFilter(
		android.content.Intent.ACTION_BATTERY_CHANGED
	);
	filter.addAction(android.os.PowerManager.ACTION_POWER_SAVE_MODE_CHANGED);
	try
	{
		if (android.os.Build.VERSION.SDK_INT >= 33)
		{
			registerReceiver(
				OpenMobileDeviceBatteryReceiver,
				filter,
				android.content.Context.RECEIVER_NOT_EXPORTED
			);
		}
		else
		{
			registerReceiver(OpenMobileDeviceBatteryReceiver, filter);
		}
		if (android.os.Build.VERSION.SDK_INT >= 29)
		{
			android.os.PowerManager powerManager = (android.os.PowerManager)
				getSystemService(android.content.Context.POWER_SERVICE);
			if (powerManager == null)
			{
				throw new IllegalStateException();
			}
			android.os.PowerManager.OnThermalStatusChangedListener listener =
				new android.os.PowerManager.OnThermalStatusChangedListener()
				{
					@Override
					public void onThermalStatusChanged(int status)
					{
						nativeOpenMobileDeviceBatteryChanged();
					}
				};
			powerManager.addThermalStatusListener(listener);
			OpenMobileDeviceThermalListener = listener;
		}
		return true;
	}
	catch (RuntimeException ignored)
	{
		AndroidThunkJava_OpenMobileDeviceStopBatteryMonitoring();
		return false;
	}
}

public void AndroidThunkJava_OpenMobileDeviceStopBatteryMonitoring()
{
	if (OpenMobileDeviceThermalListener != null
		&& android.os.Build.VERSION.SDK_INT >= 29)
	{
		android.os.PowerManager powerManager = (android.os.PowerManager)
			getSystemService(android.content.Context.POWER_SERVICE);
		if (powerManager != null)
		{
			try
			{
				powerManager.removeThermalStatusListener(
					(android.os.PowerManager.OnThermalStatusChangedListener)
						OpenMobileDeviceThermalListener
				);
			}
			catch (RuntimeException ignored)
			{
			}
		}
	}
	OpenMobileDeviceThermalListener = null;
	if (OpenMobileDeviceBatteryReceiver != null)
	{
		try
		{
			unregisterReceiver(OpenMobileDeviceBatteryReceiver);
		}
		catch (IllegalArgumentException ignored)
		{
		}
		OpenMobileDeviceBatteryReceiver = null;
	}
}
